from collections import deque
R,C=len(grid),len(grid[0]); seeds=set()
for r in range(R):
 for c in range(C):
  if grid[r][c]==5:
   for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
    rr,cc=r+dr,c+dc
    if 0<=rr<R and 0<=cc<C and grid[rr][cc]==0: seeds.add((rr,cc))
seen=set(seeds); q=deque(seeds)
while q:
 r,c=q.popleft()
 for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
  rr,cc=r+dr,c+dc
  if 0<=rr<R and 0<=cc<C and grid[rr][cc]==0 and (rr,cc) not in seen:
   seen.add((rr,cc));q.append((rr,cc))
out=[row.copy() for row in grid]
for r,c in seen: out[r][c]=5
len(seen), [' '.join(map(str,row)) for row in out]

